const source = $input.first().json;

if (!source || !Array.isArray(source.jobs)) {
  throw new Error("Jobicy response does not contain a jobs array");
}

const seen = new Set();
const result = [];

for (const job of source.jobs) {
  if (!job || typeof job !== "object" || job.id == null || typeof job.url !== "string") continue;

  let parsed;

  try {
    parsed = new URL(job.url);
  } catch {
    continue;
  }

  if (parsed.protocol !== "https:" || parsed.hostname !== "jobicy.com") continue;

  const id = String(job.id);
  if (seen.has(id)) continue;
  seen.add(id);
  result.push({ json: job });
}

return result;

const configuration = $("Configure filters").first().json;
const keywords = String(configuration.keywords || "")
  .split(",")
  .map((value) => value.trim().toLowerCase())
  .filter(Boolean);

if (!keywords.length) return $input.all();

return $input.all().filter(({ json: job }) => {
  const haystack = [
    job.jobTitle,
    job.companyName,
    job.jobGeo,
    job.jobExcerpt,
    ...(Array.isArray(job.jobIndustry) ? job.jobIndustry : [])
  ].filter(Boolean).join(" ").toLowerCase();

  return keywords.some((keyword) => haystack.includes(keyword));
});

const state = $getWorkflowStaticData("global");
const maximum = 2000;
const items = $input.all();
const previous = new Set(Array.isArray(state.jobIds) ? state.jobIds.map(String) : []);

if (state.initialized !== true) {
  state.jobIds = items.map((item) => String(item.json.id)).slice(-maximum);
  state.initialized = true;
  return [];
}

const fresh = [];

for (const item of [...items].reverse()) {
  const id = String(item.json.id);
  if (previous.has(id)) continue;
  previous.add(id);

  const escapeHtml = (value) => String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
  const title = escapeHtml(item.json.jobTitle || "Remote opportunity");
  const company = escapeHtml(item.json.companyName || "Company not specified");
  const location = escapeHtml(item.json.jobGeo || "Location not specified");
  const excerpt = escapeHtml(String(item.json.jobExcerpt || "").slice(0, 420));
  const url = escapeHtml(item.json.url);
  const lines = [`<b>${title}</b>`, `Company: ${company}`, `Location: ${location}`];

  if (excerpt) lines.push("", excerpt);
  lines.push("", `<a href="${url}">View job on Jobicy</a>`, `<a href="https://jobicy.com/">Jobs powered by Jobicy</a>`);
  fresh.push({ json: { ...item.json, telegramMessage: lines.join("\n") } });
}

state.jobIds = [...previous].slice(-maximum);
return fresh;
